function validate([grid]) {
  const n = grid.length;
  if (n < 1 || n > 10) return 'grid needs 1 to 10 rows.';
  for (const row of grid) {
    if (row.length !== n) return 'grid must be square: every row needs n values.';
    if (row.some(v => v < -100000 || v > 100000)) return 'Each value is between -10^5 and 10^5.';
  }
  return null;
}

