function sortMatrix(grid) {
  const n = grid.length;
  const sortDiagonal = (row, col, descending) => {
    const values = [];
    for (let r = row, c = col; r < n && c < n; r++, c++) {
      values.push(grid[r][c]);
    }
    values.sort((a, b) => (descending ? b - a : a - b));
    for (let r = row, c = col, k = 0; r < n && c < n; r++, c++, k++) {
      grid[r][c] = values[k];
    }
  };

  for (let row = 0; row < n; row++) {
    sortDiagonal(row, 0, true);
  }
  for (let col = 1; col < n; col++) {
    sortDiagonal(0, col, false);
  }
  return grid;
}

