function sortMatrix(grid) {
  // Bubble sort every diagonal at once: swap any two diagonal neighbours that are out of order until none are.
  const n = grid.length;
  const out = grid.map(row => row.slice());
  let swapped = true;
  while (swapped) {
    swapped = false;
    for (let i = 0; i + 1 < n; i++) {
      for (let j = 0; j + 1 < n; j++) {
        const upper = out[i][j], lower = out[i + 1][j + 1];
        // Cells with i >= j lie on or below the main diagonal, where larger values come first.
        if (i >= j ? upper < lower : upper > lower) {
          out[i][j] = lower;
          out[i + 1][j + 1] = upper;
          swapped = true;
        }
      }
    }
  }
  return out;
}

