function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(8, 10) : int(1, 5);
  // A narrow range of values gives many repeats; the full range exercises the extremes.
  const span = large || rand() < 0.4 ? 100000 : int(0, 3);
  return [Array.from({ length: n }, () => Array.from({ length: n }, () => int(-span, span)))];
}
